  "content": {
   "subject": "Your benefit award {{payload.reference}} has ended",
   "text": "Your benefit award has ended\n\nDear {{payload.subjectName}},\n\nYour benefit award has been terminated. No further payments will be made after the date shown below.\n\n  Award reference: {{payload.reference}}\n  Benefit type: {{payload.benefitType}}\n  Last day of entitlement: {{payload.terminationDate}}\n  Reason: {{payload.terminationReason}}\n  Final payment: {{payload.finalPaymentSummary}}\n\nYou have the right to appeal this decision within the statutory period.\n\nWhat happens next\n  1. Check whether any final payment is due to you.\n  2. If you believe you still qualify, contact us with supporting evidence.\n\nThank you for your co-operation.\nSocial Security Board, St. Kitts and Nevis\n\nReference {{payload.reference}}. If you have a question about this message, contact the Social Security Board and quote your reference number.",
   "html": "<h2 style=\"margin:0 0 6px 0;color:#0f172a;font-size:20px;line-height:28px;\">Your benefit award has ended</h2>\n<p style=\"margin:0 0 18px 0;color:#6b7280;font-size:13px;line-height:20px;\">Your award has been terminated from the date shown.</p>\n<p style=\"margin:0 0 14px 0;color:#111827;font-size:15px;line-height:24px;\">Dear {{payload.subjectName}},</p>\n<p style=\"margin:0 0 14px 0;color:#374151;font-size:15px;line-height:24px;\">Your benefit award has been terminated. No further payments will be made after the date shown below.</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:18px 0;border-collapse:collapse;\">\n<tbody><tr><td style=\"padding:6px 12px 6px 0;color:#4b5563;font-size:14px;vertical-align:top;white-space:nowrap;\">Award reference</td><td style=\"padding:6px 0;color:#111827;font-size:14px;font-weight:600;\">{{payload.reference}}</td></tr><tr><td style=\"padding:6px 12px 6px 0;color:#4b5563;font-size:14px;vertical-align:top;white-space:nowrap;\">Benefit type</td><td style=\"padding:6px 0;color:#111827;font-size:14px;font-weight:600;\">{{payload.benefitType}}</td></tr><tr><td style=\"padding:6px 12px 6px 0;color:#4b5563;font-size:14px;vertical-align:top;white-space:nowrap;\">Last day of entitlement</td><td style=\"padding:6px 0;color:#111827;font-size:14px;font-weight:600;\">{{payload.terminationDate}}</td></tr><tr><td style=\"padding:6px 12px 6px 0;color:#4b5563;font-size:14px;vertical-align:top;white-space:nowrap;\">Reason</td><td style=\"padding:6px 0;color:#111827;font-size:14px;font-weight:600;\">{{payload.terminationReason}}</td></tr><tr><td style=\"padding:6px 12px 6px 0;color:#4b5563;font-size:14px;vertical-align:top;white-space:nowrap;\">Final payment</td><td style=\"padding:6px 0;color:#111827;font-size:14px;font-weight:600;\">{{payload.finalPaymentSummary}}</td></tr></tbody>\n</table>\n<div style=\"margin:20px 0;padding:14px 16px;background:#f8fafc;border-left:4px solid #0f766e;\">\n<p style=\"margin:0;color:#0f172a;font-size:14px;line-height:22px;\">You have the right to appeal this decision within the statutory period.</p>\n</div>\n<h3 style=\"margin:22px 0 8px 0;color:#0f172a;font-size:15px;line-height:22px;\">What happens next</h3>\n<ol style=\"margin:0 0 16px 20px;padding:0;\"><li style=\"margin:0 0 6px 0;color:#374151;font-size:14px;line-height:22px;\">Check whether any final payment is due to you.</li><li style=\"margin:0 0 6px 0;color:#374151;font-size:14px;line-height:22px;\">If you believe you still qualify, contact us with supporting evidence.</li></ol>\n<p style=\"margin:18px 0 6px 0;color:#374151;font-size:15px;line-height:24px;\">Thank you for your co-operation.</p>\n<p style=\"margin:0 0 18px 0;color:#111827;font-size:15px;line-height:24px;\">Social Security Board, St. Kitts and Nevis</p>\n<hr style=\"border:none;border-top:1px solid #e5e7eb;margin:20px 0;\" />\n<p style=\"margin:0;color:#6b7280;font-size:12px;line-height:20px;\">Reference {{payload.reference}}. If you have a question about this message, contact the Social Security Board and quote your reference number.</p>"
  },
